public class Solution {
  /**
   * 贪心：按 from 升序（from 并列时按原下标，不影响结果）扫描，
   * 每轮把所有 from <= cur 的候选看一遍、取最大延伸 farthest，然后 cur = farthest。
   * 排序键打包进 long：高位是 from（非负，直接左移不破坏有符号序），低位是原始下标。
   * 全程只做比较，没有任何 end + 1，因此 span = Integer.MAX_VALUE 也安全。
   */
  public static int minAgentsToCover(int[] from, int[] to, int span) {
    if (from.length != to.length) throw new IllegalArgumentException("interval arrays must be parallel");
    if (span <= 0) return 0;
    int m = from.length;
    long[] keys = new long[m];
    for (int k = 0; k < m; k++) {
      if (to[k] < from[k]) throw new IllegalArgumentException("inverted interval");
      keys[k] = ((long) from[k] << 32) | (k & 0xffffffffL);
    }
    java.util.Arrays.sort(keys);
    int count = 0;
    int cur = 0;
    int p = 0;
    while (cur < span) {
      int farthest = cur;
      while (p < m && (int) (keys[p] >> 32) <= cur) {   // 所有能接上的候选
        int e = (int) keys[p];
        if (to[e] > farthest) farthest = to[e];         // 取延伸最远
        p++;
      }
      if (farthest == cur) return -1;                   // 没有进展 = 有空洞
      cur = farthest;
      count++;
    }
    return count;
  }
}

runner.naiveSolution:
public class Solution {
  // 朴素：按 from 排序后"取第一条能接上的区间"就前进，不看谁延伸得更远。
  // 起点并列时它会挑到短的那条，下一步发现更长的那条已经"过期"，直接误判为无法覆盖。
  public static int minAgentsToCover(int[] from, int[] to, int span) {
    if (from.length != to.length) throw new IllegalArgumentException("interval arrays must be parallel");
    if (span <= 0) return 0;
    int m = from.length;
    long[] keys = new long[m];
    for (int k = 0; k < m; k++) {
      if (to[k] < from[k]) throw new IllegalArgumentException("inverted interval");
      keys[k] = ((long) from[k] << 32) | (k & 0xffffffffL);
    }
    java.util.Arrays.sort(keys);
    int count = 0;
    int cur = 0;
    int p = 0;
    while (cur < span) {
      while (p < m && (int) (keys[p] >> 32) > cur) p++;
      if (p >= m) return -1;
      int e = (int) keys[p];
      if (to[e] <= cur) return -1;
      cur = to[e];
      p++;
      count++;
    }
    return count;
  }
}
